DROP TABLE IF EXISTS "product";
CREATE TABLE "product" (
	"pid"	integer,
	"name"	text,
	"price"	integer,
	"cost"	integer,
	"img"	blob,
	PRIMARY KEY("pid" AUTOINCREMENT)
);
DROP TABLE IF EXISTS "sale";
CREATE TABLE "sale" (
	"id"	integer,
	"date"	date,
	"pid"	integer,
	"price"	integer,
	"number"	integer,
	"amount"	integer,
	"cost"	integer,
	"remark"	text,
	PRIMARY KEY("id" AUTOINCREMENT)
);
